"""
Maintain–Repair–Sell decision support service.

Uses rule-based thresholds that are explicitly configurable and described
as preliminary decision rules, not financially optimal recommendations.

Recommendations support human decisions and do not replace professional
inspection or independent financial judgement.
"""

DECISION_DISCLAIMER = (
    "This recommendation is generated by preliminary, configurable decision rules. "
    "It supports human decision-making and does not replace a professional mechanical "
    "inspection or independent financial advice. Thresholds used are illustrative defaults."
)

# Configurable thresholds (explicit, not hidden)
THRESHOLDS = {
    "critical_health_score": 40,       # Below this → lean towards Sell
    "attention_health_score": 65,      # Below this → lean towards Repair
    "high_repair_cost_ratio": 0.30,    # Repair cost > 30% of resale value → Sell signal
    "high_issues_count": 4,            # >= 4 reported issues → Repair/Sell signal
    "min_records_for_recommendation": 1,  # Minimum data required
}


def generate_decision(vehicle, maintenance_records, expense_records, fuel_records) -> dict:
    """
    Generate an explainable Maintain / Repair / Sell recommendation.

    Returns:
        recommendation (str): Maintain | Repair | Sell | Insufficient Data
        confidence (str): Low | Medium | High
        reasons (list[str]): human-readable explanation
        warnings (list[str]): missing data warnings
        thresholds_used (dict): for transparency
    """
    reasons = []
    warnings = []
    sell_signals = 0
    repair_signals = 0
    maintain_signals = 0

    health_score = vehicle.health_score or 0
    health_status = vehicle.health_status or "Unknown"
    reported_issues = vehicle.reported_issues or 0
    estimated_resale = vehicle.estimated_resale_value or 0

    maint_list = list(maintenance_records)
    exp_list = list(expense_records)
    fuel_list = list(fuel_records)

    # --- Health-based signals ---
    if vehicle.health_score is None:
        warnings.append("Health score not yet calculated.")
    elif health_score < THRESHOLDS["critical_health_score"]:
        sell_signals += 2
        reasons.append(f"Health score is critically low ({health_score:.1f}/100).")
    elif health_score < THRESHOLDS["attention_health_score"]:
        repair_signals += 1
        reasons.append(f"Health score ({health_score:.1f}/100) indicates attention needed.")
    else:
        maintain_signals += 1
        reasons.append(f"Health score ({health_score:.1f}/100) is acceptable.")

    # --- Reported issues ---
    if reported_issues >= THRESHOLDS["high_issues_count"]:
        repair_signals += 1
        sell_signals += 1
        reasons.append(f"{reported_issues} reported issues — significant repair attention needed.")
    elif reported_issues > 0:
        repair_signals += 1
        reasons.append(f"{reported_issues} reported issue(s) noted.")
    else:
        maintain_signals += 1
        reasons.append("No reported issues on record.")

    # --- Repair cost vs resale value ---
    if maint_list and estimated_resale > 0:
        total_repair_cost = sum(r.cost for r in maint_list)
        ratio = total_repair_cost / estimated_resale
        if ratio > THRESHOLDS["high_repair_cost_ratio"]:
            sell_signals += 1
            reasons.append(
                f"Cumulative maintenance cost (₹{total_repair_cost:,.0f}) is "
                f"{ratio*100:.1f}% of estimated resale value (₹{estimated_resale:,.0f})."
            )
        else:
            maintain_signals += 1
            reasons.append(
                f"Maintenance costs ({ratio*100:.1f}% of resale value) are within acceptable range."
            )
    elif not maint_list:
        warnings.append("No maintenance records — repair cost analysis unavailable.")

    # --- Service history ---
    if vehicle.service_history == "Full":
        maintain_signals += 1
        maint_count = len(maint_list)
        if maint_count >= 2:
            reasons.append(f"Full documented service history ({maint_count} service events logged).")
        elif maint_count == 1:
            reasons.append("Single service record logged; owner declared full service history.")
        else:
            reasons.append("Full service history declared by owner (no individual workshop invoices uploaded).")
    elif vehicle.service_history == "None":
        sell_signals += 1
        reasons.append("No service history on file — reliability confidence reduced.")
    elif vehicle.service_history == "Partial":
        reasons.append(f"Partial service history on file ({len(maint_list)} service events recorded).")
    else:
        warnings.append("Service history unknown.")

    # --- OBD-II Diagnostic Telemetry (if available) ---
    latest_obd = getattr(vehicle, "latest_obd", None)
    if latest_obd:
        dtcs = latest_obd.dtc_list
        if dtcs:
            repair_signals += 1
            dtc_str = ", ".join(dtcs)
            reasons.append(
                f"Diagnostic record notes {len(dtcs)} active trouble code(s): {dtc_str}. "
                "Diagnostic inspection advised."
            )
            # Severe powertrain/misfire codes increase sell risk if compounded with other defects
            critical_codes = {"P0300", "P0700", "U0100", "P0301", "P0302", "P0303", "P0304"}
            if any(c in critical_codes for c in dtcs):
                sell_signals += 1
                reasons.append("Critical powertrain/CAN fault detected in OBD telemetry.")
        elif latest_obd.coolant_temp_c and latest_obd.coolant_temp_c >= 105:
            repair_signals += 1
            reasons.append(f"OBD telemetry recorded high coolant temperature ({latest_obd.coolant_temp_c}°C).")
        else:
            maintain_signals += 1
            reasons.append("OBD-II diagnostic telemetry confirms no active trouble codes detected.")
    else:
        reasons.append("No diagnostic trouble codes recorded (manual diagnostic data not logged).")

    # --- Fuel efficiency (if records exist) ---
    if fuel_list:
        total_dist = sum(r.distance_km for r in fuel_list)
        total_qty = sum(r.quantity for r in fuel_list)
        if total_dist > 0 and total_qty > 0:
            avg_eff = total_dist / total_qty
            if vehicle.fuel_type in ("Petrol", "Diesel", "Hybrid"):
                if avg_eff < 8:
                    repair_signals += 1
                    reasons.append(f"Low fuel efficiency ({avg_eff:.1f} km/L) may indicate engine issues.")
                elif avg_eff >= 14:
                    maintain_signals += 1
                    reasons.append(f"Good fuel efficiency ({avg_eff:.1f} km/L).")
            elif vehicle.fuel_type == "Electric":
                if avg_eff < 4.5:
                    repair_signals += 1
                    reasons.append(f"Below average EV efficiency ({avg_eff:.1f} km/kWh).")
                elif avg_eff >= 6.5:
                    maintain_signals += 1
                    reasons.append(f"Strong EV energy economy ({avg_eff:.1f} km/kWh).")
    else:
        warnings.append("No fuel/energy records — efficiency analysis unavailable.")

    # --- Resale value & Depreciation ---
    orig_showroom = getattr(vehicle, "original_showroom_price", None)
    curr_market = getattr(vehicle, "current_market_price", None)

    if orig_showroom and orig_showroom > 0 and estimated_resale > 0:
        deprec_amt = orig_showroom - estimated_resale
        deprec_pct = (deprec_amt / orig_showroom) * 100.0
        if deprec_pct >= 72.0:
            sell_signals += 1
            reasons.append(
                f"Significant cumulative depreciation ({deprec_pct:.1f}% decline from original ex-showroom price ₹{orig_showroom:,.0f})."
            )
        elif deprec_pct <= 35.0:
            maintain_signals += 1
            reasons.append(
                f"Strong equity retention ({100.0 - deprec_pct:.1f}% preserved of original ex-showroom price ₹{orig_showroom:,.0f})."
            )
        else:
            reasons.append(
                f"Moderate equity retention: {deprec_pct:.1f}% depreciation from original ex-showroom price ₹{orig_showroom:,.0f}."
            )

    if curr_market and curr_market > 0 and estimated_resale > 0:
        if estimated_resale < curr_market * 0.82:
            reasons.append(
                f"Resale value reflects condition/defect adjustments relative to prevailing market asking average (₹{curr_market:,.0f})."
            )
        else:
            reasons.append(
                f"Resale valuation is consistent with current comparable market asking price (₹{curr_market:,.0f})."
            )

    if estimated_resale > 0:
        if estimated_resale < 200_000:
            sell_signals += 1
            reasons.append(f"Estimated resale value is low (₹{estimated_resale:,.0f}).")
        elif not orig_showroom:
            reasons.append(f"Estimated resale value: ₹{estimated_resale:,.0f}.")
    else:
        warnings.append("Resale value not estimated.")

    # --- Determine recommendation ---
    total_signals = sell_signals + repair_signals + maintain_signals
    if total_signals < THRESHOLDS["min_records_for_recommendation"]:
        return {
            "recommendation": "Insufficient Data",
            "confidence": "Low",
            "confidence_rationale": "Sparse vehicle telemetry and service history.",
            "reasons": ["Not enough data to generate a recommendation."],
            "warnings": warnings,
            "thresholds_used": THRESHOLDS,
            "disclaimer": DECISION_DISCLAIMER,
        }

    if sell_signals >= 3:
        recommendation = "Sell"
    elif sell_signals >= 2 and sell_signals > maintain_signals:
        recommendation = "Sell"
    elif repair_signals >= 2 or (repair_signals >= 1 and sell_signals >= 1):
        recommendation = "Repair"
    elif maintain_signals >= sell_signals and maintain_signals >= repair_signals:
        recommendation = "Maintain"
    else:
        recommendation = "Repair"

    # Defined confidence levels based on operational data completeness:
    if len(maint_list) >= 2 and len(fuel_list) >= 1 and estimated_resale > 0 and vehicle.health_score is not None:
        confidence = "High"
        confidence_rationale = "High confidence: Multi-source operational history available (maintenance invoices, fuel consumption, and condition score)."
    elif len(maint_list) >= 1 or len(fuel_list) >= 1 or latest_obd is not None:
        confidence = "Medium"
        confidence_rationale = "Medium confidence: Partial operational history available to support rule-based evaluation."
    else:
        confidence = "Low"
        confidence_rationale = "Preliminary confidence: Limited history logged; evaluation based primarily on baseline vehicle profile."

    return {
        "recommendation": recommendation,
        "confidence": confidence,
        "confidence_rationale": confidence_rationale,
        "reasons": reasons,
        "warnings": warnings,
        "thresholds_used": THRESHOLDS,
        "disclaimer": DECISION_DISCLAIMER,
        "signal_counts": {
            "maintain": maintain_signals,
            "repair": repair_signals,
            "sell": sell_signals,
        },
    }

